from typing import List, NamedTuple, Union, Optional, Tuple
import ast
import operator
import argparse

# --- Data Structures ---

class AuditEntry(NamedTuple):
    """Immutable record of an operation."""
    operation: str
    args: Tuple[float, ...]
    result: Optional[float]

    def __str__(self) -> str:
        """Returns a human-readable string representation of the operation."""
        args_str = ", ".join(map(str, self.args))
        res_str = f" = {self.result}" if self.result is not None else ""
        return f"{self.operation.upper()}({args_str}){res_str}"

# --- Calculator Logic (Core) ---

class Calculator:
    """
    Core calculator engine handling arithmetic, audit logging, and expression evaluation.
    """
    def __init__(self) -> None:
        self._history: List[AuditEntry] = []
        self._memory: Optional[float] = None  # Persistent memory state

    def _log(self, op: str, args: Tuple[float, ...], res: Optional[float]) -> None:
        """Logs operation details to history using AuditEntry."""
        self._history.append(AuditEntry(op, args, res))

    def add(self, a: float, b: float) -> float:
        res = a + b
        self._log("add", (a, b), res)
        return res

    def subtract(self, a: float, b: float) -> float:
        res = a - b
        self._log("subtract", (a, b), res)
        return res

    def multiply(self, a: float, b: float) -> float:
        res = a * b
        self._log("multiply", (a, b), res)
        return res

    def divide(self, a: float, b: float) -> float:
        if b == 0:
            raise ValueError("Cannot divide by zero.")
        res = a / b
        self._log("divide", (a, b), res)
        return res

    def power(self, base: float, exponent: float) -> float:
        res = pow(base, exponent)
        if isinstance(res, complex):
            raise ValueError("Result is imaginary.")
        val = float(res)
        self._log("power", (base, exponent), val)
        return val

    def modulo(self, a: float, b: float) -> float:
        if b == 0:
            raise ValueError("Cannot perform modulo by zero.")
        res = a % b
        self._log("modulo", (a, b), res)
        return res

    def memory_store(self, value: float) -> None:
        self._memory = value
        self._log("memory_store", (value,), None)

    def memory_recall(self) -> float:
        if self._memory is None:
            raise ValueError("Memory is empty.")
        self._log("memory_recall", (), self._memory)
        return self._memory

    def memory_clear(self) -> None:
        self._memory = None
        self._log("memory_clear", (), None)

    def get_history(self) -> List[AuditEntry]:
        return self._history.copy()

    def clear_history(self) -> None:
        self._history.clear()

    def evaluate(self, expression: str) -> float:
        """
        Parses and evaluates a mathematical string expression using AST.
        Records only the final result as one history entry.
        """
        ops = {
            ast.Add: operator.add,
            ast.Sub: operator.sub,
            ast.Mult: operator.mul,
            ast.Div: operator.truediv,
            ast.Pow: operator.pow,
            ast.Mod: operator.mod
        }

        def _eval(node):
            if isinstance(node, ast.Constant):
                return float(node.value)
            elif isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
                op_type = type(node.op)
                if op_type in ops:
                    return ops[op_type](left, right)
                raise ValueError(f"Unsupported operator: {op_type}")
            elif isinstance(node, ast.UnaryOp):
                if isinstance(node.op, ast.USub):
                    return -_eval(node.operand)
                elif isinstance(node.op, ast.UAdd):
                    return _eval(node.operand)
                raise ValueError("Unsupported unary operator")
            elif isinstance(node, ast.Expr):
                return _eval(node.value)
            else:
                raise ValueError(f"Unsupported expression structure: {type(node)}")

        try:
            tree = ast.parse(expression, mode='eval')
            result = float(_eval(tree.body))
            # Records one entry for the entire expression evaluation
            self._log("evaluate", (0.0,), result)
            return result
        except (SyntaxError, TypeError, ValueError) as e:
            raise ValueError(f"Malformed expression: {e}")

